#!/usr/bin/env python3
"""Data view -> full statistics page for the DEV classic station pages (dev only).

Rebuilds stations/USGS-<id>.html (classic pages only; -3d pages are skipped)
as statistics pages per Saurabh's directive: the WebGL scene, terrain and
satellite imagery, instrument meshes and VR affordances are removed entirely,
and the page's statistical substance is reorganized top-down: header, record
stats cards (computed from the page's own baked series), hydrograph (full
record + the original last-90-days board), the 7-day forecast section with
the ht-dacp confidence-interval panel, model statistics (per-station test-era
leaderboard, pooled CMP_RMSE leaderboard, per-lead RMSE matrix), the feature
ablation panel and the drift panel.

How: the original module script is replaced by a DOM app that reuses the
page's own data head (HT_DATA handling, predFor/ivFor incl. the DACP hooks,
rmse, COLS, state), its canvas drawing functions (drawBoard, drawDayPanel,
drawFcPanel, drawColumnPanel) and its state actions VERBATIM - only the
host changes (DOM canvases instead of WebGL textures) and applyDay becomes
charts-only. window.HT_DATA is never modified (asserted byte-identical).
Existing DOM blocks (#ht-datewrap, #featcpanel, #ht-drift-panel and the
runtime-created #ht-dacp-panel) are relocated into the layout at load and
de-fixed by CSS overrides. The classic pages' stale ablation block is
replaced with the per-station 25-year values (identical to the 3D pages).
No fetches are added; classic pages had no geology/watershed live panels
(the geology content was Dallas-only scene scenery and goes with the scene).

Idempotent: pages carrying the MARKER are skipped.
Run from the repo root: python3 build25/patch_statsview.py
"""
import html
import json
import re
import sys
from datetime import date, timedelta
from pathlib import Path

MARKER = "ht-statsview v1"

APP_JS = '/* ht-statsview v1 - Data view rebuilt as a full statistics page (dev).\n * The WebGL scene, terrain/satellite imagery and VR affordances are removed;\n * the original page\'s data head, chart drawing and forecast logic run verbatim\n * on DOM canvases. Data payload (window.HT_DATA) is untouched. */\n\'use strict\';\n// ---------------------------------------------------------------- data\nconst D = window.HT_DATA;\n// ---- gap layer (10-year pages): keep the measured values, and a display copy that repeats the last measured day\nconst RAWV = {}, GAPDAY = new Array(D.n).fill(false);\n// display value on a gap day: flow / rising repeat the last measured day; weather is drawn neutral (mild, dry)\nconst NEUTRAL = { tmax: 18, tmin: 10, tmean: 14, precip: 0 };\n[\'tmax\', \'tmin\', \'tmean\', \'precip\', \'flow\', \'rising\'].forEach((k) => {\n  RAWV[k] = D[k].slice(); const first = D[k].find((v) => v != null); let last = first;\n  D[k] = D[k].map((v, i) => { if (v == null) { GAPDAY[i] = true; return k in NEUTRAL ? NEUTRAL[k] : last; } last = v; return v; });\n});\nconst fmtAt = (C, i) => RAWV[C.key][i] == null ? \'no data\' : C.fmt(C.v[i]);\nconst N = D.n, L = D.pred[0].length, M = D.models.length;\nconst day0 = Date.parse(D.start + \'T00:00:00Z\');\nconst dateOf = (i) => new Date(day0 + i * 864e5);\nconst fmt = (i, opt) => dateOf(i).toLocaleDateString(\'en-GB\', Object.assign({ timeZone: \'UTC\' }, opt || { day: \'2-digit\', month: \'short\', year: \'numeric\' }));\nconst COL = [\'#2F80D1\', \'#E0852A\', \'#9E61CC\', \'#D1495B\', \'#8A8F98\', \'#1BA3A3\', \'#E36BA8\', \'#4D6E8A\'];   // 12 colours for the 12-model pages\n\nlet fmin = Infinity, fmax = -Infinity;\nfor (const v of D.flow) { fmin = Math.min(fmin, v); fmax = Math.max(fmax, v); }\nfor (const m of D.pred) for (const l of m) for (const v of l) if (v != null) { fmin = Math.min(fmin, v); fmax = Math.max(fmax, v); }\nif (D.hi) for (const m of D.hi) for (const l of m) for (const v of l) if (v != null) fmax = Math.max(fmax, v);\nfmin = Math.max(1, fmin);\nconst lnorm = (v) => Math.min(1, Math.max(0, (Math.log(v) - Math.log(fmin)) / (Math.log(fmax) - Math.log(fmin))));\nconst LOWY = 1.25, HIGHY = 2.7, level = (v) => LOWY + (HIGHY - LOWY) * lnorm(v);\nlet tmin = Infinity, tmax = -Infinity;\nfor (let i = 0; i < N; i++) { tmin = Math.min(tmin, D.tmin[i]); tmax = Math.max(tmax, D.tmax[i]); }\nconst tnorm = (t) => (t - tmin) / (tmax - tmin);\n\nconst predFor = (m, issue, lead) => (issue >= 0 && issue < N) ? D.pred[m][lead - 1][issue] : null;\nconst actualAt = (i) => (i >= 0 && i < N) ? RAWV.flow[i] : null;\n// 80% interval (from validation residuals) when predictions.csv has lo_cfs / hi_cfs\nconst ivFor = (m, issue, lead) => { const R = (typeof window !== \'undefined\' && window.__dacpIv) ? window.__dacpIv(m, issue, lead) : null; if (R) return R; return (D.lo && issue >= 0 && issue < N && D.lo[m][lead - 1][issue] != null) ? [Math.max(1, D.lo[m][lead - 1][issue]), D.hi[m][lead - 1][issue]] : null; };\nconst fmtQ = (v) => Math.round(v).toLocaleString(\'en-US\');\n\n// RMSE of log flow per model and lead\nconst rmse = D.models.map((_, m) => Array.from({ length: L }, (_, l) => {\n  let s = 0, n = 0;\n  for (let i = 0; i + l + 1 < N; i++) { const p = D.pred[m][l][i]; if (p == null || RAWV.flow[i + l + 1] == null) continue; const e = Math.log(p) - Math.log(RAWV.flow[i + l + 1]); s += e * e; n++; }\n  return Math.sqrt(s / n);\n}));\nconst bestModel = (lead) => rmse.reduce((b, r, m) => r[lead - 1] < rmse[b][lead - 1] ? m : b, 0);\n\n// ---------------------------------------------------------------- the six dataset columns\nconst WIN = 29;                                       // model input window (days)\nconst TRAIN_LAST = dayIndex(D.trainLast || \'2024-06-29\');            // last input day of the last training window\nconst COLS = [\n  { key: \'tmax\', col: \'tmax_c\', name: \'Daily high temperature\', src: \'NOAA GHCN-Daily · TMAX\', unit: \'°C\', color: \'#D1495B\', v: D.tmax, why: \'Drives snowmelt and evaporation\' },\n  { key: \'tmin\', col: \'tmin_c\', name: \'Daily low temperature\', src: \'NOAA GHCN-Daily · TMIN\', unit: \'°C\', color: \'#3A6FE0\', v: D.tmin, why: \'Separates freezing nights from thawing ones\' },\n  { key: \'tmean\', col: \'tmean_c\', name: \'Daily mean temperature\', src: \'NOAA GHCN-Daily · TAVG\', unit: \'°C\', color: \'#E08A2B\', v: D.tmean, why: \'Overall warmth of the day\' },\n  { key: \'precip\', col: \'precip_mm\', name: \'Total precipitation\', src: \'NOAA GHCN-Daily · PRCP\', unit: \'mm\', color: \'#2F80D1\', v: D.precip, why: \'Water arriving at the surface\' },\n  { key: \'flow\', col: \'flow_cfs\', name: "Today\'s river flow", src: \'USGS 08057000 · 00060 daily mean\', unit: \'cfs\', color: \'#1BA3A3\', v: D.flow, why: \'Where the river stands and, shifted forward, the variable being predicted\' },\n  { key: \'rising\', col: \'rising\', name: \'Rising or falling\', src: \'USGS 08057000 · flow > yesterday\', unit: \'\', color: \'#2E9B57\', v: D.rising, why: \'A climbing river and a draining one behave differently at the same level\' },\n];\nif (D.station && D.station.columnSources) COLS.forEach((c) => { if (D.station.columnSources[c.col]) c.src = D.station.columnSources[c.col]; });\nCOLS.forEach((c) => {\n  c.min = Math.min(...c.v); c.max = Math.max(...c.v);\n  const last = Math.min(TRAIN_LAST, N - 1);            // standardisation stats: training input days only\n  if (last >= WIN) { let s = 0, s2 = 0; for (let i = 0; i <= last; i++) { s += c.v[i]; s2 += c.v[i] * c.v[i]; }\n    c.mu = s / (last + 1); c.sd = Math.sqrt(Math.max(1e-9, s2 / (last + 1) - c.mu * c.mu)); }\n  c.norm = c.key === \'flow\' ? lnorm : c.key === \'rising\' ? (x) => (x ? 0.5 : 0.1) : (x) => (x - c.min) / ((c.max - c.min) || 1);\n  c.fmt = (x) => c.key === \'rising\' ? (x ? \'rising (1)\' : \'falling (0)\') : c.key === \'flow\' ? `${Math.round(x).toLocaleString(\'en-US\')} cfs` : `${(+x).toFixed(1)} ${c.unit}`;\n});\n\n// ---------------------------------------------------------------- state\nconst params = new URLSearchParams(location.search);\nconst S = {\n  day: Math.min(D.n - 1, params.has(\'day\') ? Math.max(0, dayIndex(params.get(\'day\'))) : D.openDay && params.get(\'latest\') !== \'1\' ? dayIndex(D.openDay) : (params.get(\'latest\') === \'1\' || D.live ? D.n - 1 : 200)),\n  lead: +(params.get(\'lead\') || 1),\n  model: 0, compare: params.get(\'compare\') === \'1\', playing: false, speed: 6,\n  focus: COLS.findIndex((c) => c.key === params.get(\'focus\')),   // -1 = forecast view\n};\nfunction dayIndex(iso) { return Math.round((Date.parse(iso + \'T00:00:00Z\') - day0) / 864e5); }\nS.model = params.has(\'model\') ? Math.max(0, D.models.indexOf(params.get(\'model\'))) : (D.live || D.station ? 0 : bestModel(S.lead));\nwindow.__htS = S;   // live pages list the selected model first\n\n// ---------------------------------------------------------------- DOM panels (statistics view: the WebGL scene is gone)\nfunction canvasPlane(w, h, pxPerUnit = 220) {\n  const c = document.createElement(\'canvas\'); c.width = Math.round(w * pxPerUnit); c.height = Math.round(h * pxPerUnit);\n  return { c, g: c.getContext(\'2d\'), tex: { needsUpdate: false }, k: pxPerUnit };\n}\nconst ST = D.station;\nconst MAP_URL = D.station && D.station.mapUrl;\nconst B = canvasPlane(7.4, 3.4, 180);\n\nfunction drawBoard() {\n  const { g, c } = B, W = c.width, H = c.height, pad = 60, top = 90, bot = H - 40, win = 90;\n  g.fillStyle = \'#14223A\'; g.beginPath(); g.roundRect(0, 0, W, H, 30); g.fill();\n  g.fillStyle = \'#F5F6F2\'; g.font = \'600 44px Arial\'; g.fillText(\'Last 90 days of flow\', pad, 60);\n  g.fillStyle = \'#6FB0F0\'; g.fillText(\'— observed\', 560, 60);\n  g.fillStyle = COL[S.model]; g.fillText(`— ${D.models[S.model]} +${S.lead}d`, 850, 60);\n  const start = Math.max(0, S.day - win + 1), cols = win + L;\n  const X = (i) => pad + (i - start) / (cols - 1) * (W - 2 * pad), Y = (v) => bot - lnorm(v) * (bot - top);\n  g.strokeStyle = \'rgba(255,255,255,0.12)\'; g.lineWidth = 2;\n  for (let k = 0; k <= 4; k++) { g.beginPath(); g.moveTo(pad, top + k * (bot - top) / 4); g.lineTo(W - pad, top + k * (bot - top) / 4); g.stroke(); }\n  const line = (get, color, w, dash) => { g.strokeStyle = color; g.lineWidth = w; g.setLineDash(dash || []); g.beginPath(); let first = true;\n    for (let i = start; i <= S.day; i++) { const v = get(i); if (v == null) continue; first ? g.moveTo(X(i), Y(v)) : g.lineTo(X(i), Y(v)); first = false; } g.stroke(); g.setLineDash([]); };\n  line((i) => RAWV.flow[i], \'#6FB0F0\', 7);\n  line((i) => predFor(S.model, i - S.lead, S.lead), COL[S.model], 5, [14, 10]);\n  // 80% interval band past today\n  const ivs = Array.from({ length: L }, (_, k) => ivFor(S.model, S.day, k + 1));\n  if (ivs.every((v) => v)) {\n    g.fillStyle = COL[S.model]; g.globalAlpha = 0.28; g.beginPath(); g.moveTo(X(S.day), Y(D.flow[S.day]));\n    ivs.forEach((v, k) => g.lineTo(X(S.day + k + 1), Y(v[1])));\n    for (let k = L - 1; k >= 0; k--) g.lineTo(X(S.day + k + 1), Y(ivs[k][0]));\n    g.closePath(); g.fill(); g.globalAlpha = 1;\n    g.font = \'600 44px Arial\'; const lx = 850 + g.measureText(`— ${D.models[S.model]} +${S.lead}d`).width + 30; g.fillStyle = COL[S.model]; g.globalAlpha = 0.5; g.fillRect(lx, 36, 30, 30); g.globalAlpha = 1; g.fillStyle = \'#F5F6F2\'; g.font = \'32px Arial\'; g.fillText(window.__dacpLabel || \'80%\', lx + 40, 62);\n  }\n  // 7-day fan past today\n  g.strokeStyle = COL[S.model]; g.lineWidth = 7; g.beginPath(); g.moveTo(X(S.day), Y(D.flow[S.day]));\n  for (let l = 1; l <= L; l++) { const p = predFor(S.model, S.day, l); if (p != null) g.lineTo(X(S.day + l), Y(p)); } g.stroke();\n  g.fillStyle = \'#FFD24D\'; g.beginPath(); g.arc(X(S.day), Y(D.flow[S.day]), 12, 0, 7); g.fill();\n  g.strokeStyle = \'rgba(255,255,255,0.4)\'; g.setLineDash([8, 8]); g.beginPath(); g.moveTo(X(S.day), top); g.lineTo(X(S.day), bot); g.stroke(); g.setLineDash([]);\n  g.fillStyle = \'#BFD0E0\'; g.font = \'32px Arial\'; g.fillText(\'today\', X(S.day) - 40, bot + 34);\n  B.tex.needsUpdate = true;\n}\n\nconst dayPanel = canvasPlane(2.0, 1.35, 400);\nconst fcPanel = canvasPlane(2.1, 1.45, 420);\n// period of the chosen issue day (pages built with periods = true)\nconst periodOf = (i) => !D.periods ? null : i <= dayIndex(D.trainLast) ? [\'TRAIN (seen)\', \'#B8C4D0\'] : i <= dayIndex(D.valLast) ? [\'VALIDATION\', \'#8FC1F2\'] : [\'TEST (unseen)\', \'#FFD24D\'];\n\nconst BTN = { next: [0.03, 0.83, 0.23, 0.14], lead: [0.27, 0.83, 0.23, 0.14], cmp: [0.51, 0.83, 0.23, 0.14], play: [0.75, 0.83, 0.22, 0.14] };\nconst SLIDER = [0.05, 0.80, 0.9, 0.1];\nconst ROW = (r) => [0.02, (140 + r * 52 - 40) / 540, 0.96, 52 / 540];   // day-panel row r (uv box)\n\nfunction drawDayPanel() {\n  const { g, c } = dayPanel, W = c.width, H = c.height, i = S.day;\n  g.clearRect(0, 0, W, H); g.fillStyle = \'rgba(12,18,28,0.97)\'; g.beginPath(); g.roundRect(0, 0, W, H, 30); g.fill();\n  g.fillStyle = \'#F5F6F2\'; g.font = \'600 56px Arial\'; g.fillText(fmt(i, { weekday: \'short\', day: \'2-digit\', month: \'short\', year: \'numeric\' }), 40, 80);\n  { const pr = periodOf(i); if (pr) { g.font = \'600 26px Arial\'; g.fillStyle = pr[1]; g.textAlign = \'right\'; g.fillText(pr[0], W - 30, 80); g.textAlign = \'left\'; } }\n  if (GAPDAY[i]) { g.fillStyle = \'#FF8A6B\'; g.font = \'600 22px Arial\'; g.fillText(\'gap day: missing values = "no data" (scenery drawn neutral)\', 40, 106); }\n  if (ST && ST.sources) { g.fillStyle = \'#8FC1F2\'; g.font = \'22px Arial\'; g.textAlign = \'right\'; g.fillText(ST.sources, W - 30, 24); g.textAlign = \'left\'; }\n  COLS.forEach((C, r) => {\n    const y = 140 + r * 52;\n    if (r === S.focus) { g.fillStyle = \'rgba(143,193,242,0.18)\'; g.fillRect(16, y - 40, W - 32, 52); }\n    g.fillStyle = C.color; g.fillRect(28, y - 28, 10, 34);\n    g.font = \'600 32px Courier New\'; g.fillStyle = \'#CFE0F2\'; g.fillText(C.col, 52, y);\n    g.font = \'32px Arial\'; g.fillStyle = \'#9FB3C8\'; g.fillText(C.name.replace(\'Daily \', \'\').replace("Today\'s ", \'\'), 270, y);\n    g.fillStyle = \'#F5F6F2\'; g.textAlign = \'right\'; g.fillText(fmtAt(C, i), W - 36, y); g.textAlign = \'left\';\n  });\n  const [sx, sy, sw, sh] = SLIDER.map((v, k) => v * (k % 2 ? H : W));\n  g.fillStyle = \'#34445C\'; g.fillRect(sx, sy + sh / 2 - 6, sw, 12);\n  g.fillStyle = \'#8FC1F2\'; g.beginPath(); g.arc(sx + sw * i / (N - 1), sy + sh / 2, 22, 0, 7); g.fill();\n  g.fillStyle = \'#9FB3C8\'; g.font = \'28px Arial\';\n  g.fillText((S.playing ? \'playing — X pause\' : \'paused — X play\') + \' · trigger a row to focus that column\', 40, H - 18);\n  dayPanel.tex.needsUpdate = true;\n}\nfunction wrapText(g, text, x, y, maxW, lh) {\n  let line = \'\';\n  for (const w of text.split(\' \')) { const t = line ? line + \' \' + w : w; if (g.measureText(t).width > maxW && line) { g.fillText(line, x, y); y += lh; line = w; } else line = t; }\n  if (line) g.fillText(line, x, y); return y + lh;\n}\nfunction drawColumnPanel() {\n  const { g, c } = fcPanel, W = c.width, H = c.height, C = COLS[S.focus], i = S.day, k = S.focus;\n  g.clearRect(0, 0, W, H); g.fillStyle = \'rgba(12,18,28,0.92)\'; g.beginPath(); g.roundRect(0, 0, W, H, 30); g.fill();\n  g.fillStyle = C.color; g.font = \'600 50px Arial\'; g.fillText(C.name, 40, 72);\n  g.font = \'600 30px Courier New\'; g.fillStyle = \'#CFE0F2\'; g.fillText(`${C.col} · input channel ${k + 1}/6`, 40, 118);\n  g.font = \'30px Arial\'; g.fillStyle = \'#9FB3C8\'; g.fillText(\'Source: \' + C.src, 40, 158);\n  g.font = \'28px Arial\'; let y = wrapText(g, \'Why: \' + C.why, 40, 196, W - 80, 34);\n  const w0 = Math.max(0, i - WIN + 1), win = C.v.slice(w0, i + 1);\n  const mean = win.reduce((a, b) => a + b, 0) / win.length;\n  g.fillStyle = \'#F5F6F2\'; g.font = \'600 34px Arial\';\n  g.fillText(`Today ${fmt(i, { day: \'2-digit\', month: \'short\', year: \'numeric\' })}:  ${fmtAt(C, i)}`, 40, y + 8); y += 50;\n  g.fillStyle = \'#9FB3C8\'; g.font = \'28px Arial\';\n  g.fillText(C.key === \'rising\' ? `Window (${win.length} d): ${win.filter((v) => v).length} rising, ${win.filter((v) => !v).length} falling`\n    : `Window (${win.length} d): min ${C.fmt(Math.min(...win))} · max ${C.fmt(Math.max(...win))}`, 40, y); y += 40;\n  if (C.mu != null) g.fillText(`Scaled: (x − ${C.mu.toFixed(1)}) / ${C.sd.toFixed(1)}  →  today z = ${((C.v[i] - C.mu) / C.sd).toFixed(2)}`, 40, y);\n  else g.fillText(\'Scaled with training-day mean and sd only\', 40, y);\n  y += 40;\n  if (C.key === \'flow\') { g.fillStyle = COL[S.model]; g.fillText(`Also the target: ${D.models[S.model]} forecasts +1…+7 d`, 40, y); }\n  const names = { next: \'Next column (A)\', lead: \'Prev column (B)\', cmp: \'Forecast view (Y)\', play: S.playing ? \'Pause (X)\' : \'Play (X)\' };\n  for (const [kk, [bx, by, bw, bh]] of Object.entries(BTN)) {\n    g.fillStyle = \'#23466E\'; g.beginPath(); g.roundRect(bx * W, by * H, bw * W, bh * H, 16); g.fill();\n    g.fillStyle = \'#F5F6F2\'; g.font = \'600 25px Arial\'; g.textAlign = \'center\'; g.fillText(names[kk], (bx + bw / 2) * W, (by + bh / 2) * H + 9); g.textAlign = \'left\';\n  }\n  fcPanel.tex.needsUpdate = true;\n}\nfunction drawFcPanel() {\n  if (S.focus >= 0) return drawColumnPanel();\n  const { g, c } = fcPanel, W = c.width, H = c.height;\n  g.clearRect(0, 0, W, H); g.fillStyle = \'rgba(12,18,28,0.97)\'; g.beginPath(); g.roundRect(0, 0, W, H, 30); g.fill();\n  g.font = \'600 54px Arial\';\n  if (S.compare) { g.fillStyle = \'#F5F6F2\'; g.fillText(`All models · +${S.lead}d forecast`, 40, 80); }\n  else { g.fillStyle = COL[S.model]; g.fillText(D.models[S.model], 40, 80); g.fillStyle = \'#F5F6F2\'; g.fillText(`· lead +${S.lead}d`, 40 + g.measureText(D.models[S.model]).width + 20, 80); }\n  g.font = \'600 30px Arial\'; g.fillStyle = \'#9FB3C8\';\n  const cx = [30, 120, 270, 610, 770], cr = 400;\n  (S.compare ? [\'Model\', \'\', \'Forecast\', \'Observed\', \'Error\'] : [\'Lead\', \'Date\', \'Forecast\', \'Observed\', \'Error\']).forEach((h, k) => g.fillText(h, cx[k], 140));\n  if (!S.compare && D.lo) g.fillText(\'80% range\', cr, 140);\n  g.font = \'32px Arial\';\n  const rows = S.compare ? D.models.map((mn, m) => [mn, \'\', predFor(m, S.day, S.lead), actualAt(S.day + S.lead), m])\n    : Array.from({ length: L }, (_, k) => [`+${k + 1}d`, fmt(S.day + k + 1, { day: \'2-digit\', month: \'short\' }), predFor(S.model, S.day, k + 1), actualAt(S.day + k + 1), -1]);\n  rows.forEach(([a, b, p, o, m], r) => {\n    const y = 186 + r * (rows.length > 9 ? 24 : rows.length > 7 ? 35 : 42); if (rows.length > 9) g.font = \'24px Arial\';\n    if (!S.compare && r + 1 === S.lead) { g.fillStyle = \'rgba(143,193,242,0.15)\'; g.fillRect(24, y - 34, W - 48, 44); }\n    g.fillStyle = m >= 0 ? COL[m] : \'#F5F6F2\'; g.fillText(a, cx[0], y);\n    g.fillStyle = \'#F5F6F2\'; g.fillText(b, cx[1], y);\n    g.fillText(p == null ? \'—\' : fmtQ(p), cx[2], y); g.fillText(o == null ? \'—\' : fmtQ(o), cx[3], y);\n    const iv = S.compare ? null : ivFor(S.model, S.day, r + 1);\n    if (iv) { g.fillStyle = \'#FFD24D\'; g.fillText(`${fmtQ(iv[0])}–${fmtQ(iv[1])}`, cr, y); g.fillStyle = \'#F5F6F2\'; }\n    if (p != null && o != null) { const e = Math.round((p - o) / o * 100); g.fillStyle = Math.abs(e) > 20 ? \'#F0A865\' : \'#9FD8A8\'; g.fillText((e >= 0 ? \'+\' : \'\') + e + \'%\', cx[4], y); }\n  });\n  const rank = 1 + rmse.filter((r) => r[S.lead - 1] < rmse[S.model][S.lead - 1]).length;\n  g.fillStyle = \'#9FB3C8\'; g.font = \'32px Arial\';\n  g.fillText(`${D.models[S.model]} at +${S.lead}d over the record: RMSE ${rmse[S.model][S.lead - 1].toFixed(3)} (log) · rank ${rank} of ${M}`, 40, H * 0.79);\n  // buttons\n  const names = { next: \'Next model (A)\', lead: \'Next lead (B)\', cmp: S.compare ? \'Single (Y)\' : \'Compare (Y)\', play: S.playing ? \'Pause (X)\' : \'Play (X)\' };\n  for (const [k, [bx, by, bw, bh]] of Object.entries(BTN)) {\n    g.fillStyle = \'#23466E\'; g.beginPath(); g.roundRect(bx * W, by * H, bw * W, bh * H, 16); g.fill();\n    g.fillStyle = \'#F5F6F2\'; g.font = \'600 32px Arial\'; g.textAlign = \'center\'; g.fillText(names[k], (bx + bw / 2) * W, (by + bh / 2) * H + 11); g.textAlign = \'left\';\n  }\n  fcPanel.tex.needsUpdate = true;\n}\n\nconst goMap = () => { if (MAP_URL) location.href = MAP_URL; };\nfunction setFocus(f) { S.focus = ((f + 1 + COLS.length + 1) % (COLS.length + 1)) - 1; applyDay(); }\nfunction setDay(i) { S.day = Math.max(0, Math.min(N - 1, i)); applyDay(); htSyncDate(); }\nfunction htIsoDay(i){ return new Date(day0 + i*864e5).toISOString().slice(0,10); }\nfunction htSyncDate(){ var el = document.getElementById(\'ht-date\'); if (el && document.activeElement !== el) el.value = htIsoDay(S.day); }\n\nfunction htDateInit(){ var el = document.getElementById(\'ht-date\'); if(!el) return; el.value = htIsoDay(S.day);\n  el.addEventListener(\'change\', function(){ if(el.value) setDay(dayIndex(el.value)); }); }\nconst act = {\n  next: () => { if (S.focus >= 0) return setFocus(S.focus + 1); S.model = (S.model + 1) % M; applyDay(); },\n  lead: () => { if (S.focus >= 0) return setFocus(S.focus - 1); S.lead = S.lead % L + 1; applyDay(); },\n  cmp: () => { if (S.focus >= 0) return setFocus(-1); S.compare = !S.compare; applyDay(); },\n  col: (d = 1) => setFocus(S.focus + d),\n  play: () => { S.playing = !S.playing; drawDayPanel(); drawFcPanel(); },\n};\n\n// ---------------------------------------------------------------- full-record overview + per-lead table (DOM additions)\nconst OV_PADL = 64, OV_PADR = 14;\nfunction drawOverview() {\n  const cv = document.getElementById(\'hts-overview\'); if (!cv) return;\n  const g = cv.getContext(\'2d\'), W = cv.width, H = cv.height, padT = 12, padB = 22;\n  g.clearRect(0, 0, W, H); g.fillStyle = \'#0E1A24\'; g.fillRect(0, 0, W, H);\n  const X = (i) => OV_PADL + (i / (N - 1)) * (W - OV_PADL - OV_PADR), Y = (v) => padT + (1 - lnorm(v)) * (H - padT - padB);\n  g.font = \'20px Arial\'; g.textAlign = \'right\';\n  [0, 0.25, 0.5, 0.75, 1].forEach((q) => { const v = Math.exp(Math.log(fmin) + q * (Math.log(fmax) - Math.log(fmin))); const y = padT + (1 - q) * (H - padT - padB);\n    g.strokeStyle = \'rgba(255,255,255,0.10)\'; g.lineWidth = 1; g.beginPath(); g.moveTo(OV_PADL, y); g.lineTo(W - OV_PADR, y); g.stroke();\n    g.fillStyle = \'#9FB3C8\'; g.fillText(fmtQ(v), OV_PADL - 8, y + 6); });\n  g.textAlign = \'left\';\n  const w0 = Math.max(0, S.day - 89);\n  g.fillStyle = \'rgba(143,193,242,0.10)\'; g.fillRect(X(w0), padT, Math.max(1, X(S.day) - X(w0)), H - padT - padB);\n  g.strokeStyle = \'rgba(255,255,255,0.07)\'; g.fillStyle = \'#9FB3C8\'; g.font = \'18px Arial\';\n  for (let i = 0; i < N; i++) { const d = dateOf(i); if (d.getUTCMonth() === 0 && d.getUTCDate() === 1) { g.beginPath(); g.moveTo(X(i), padT); g.lineTo(X(i), H - padB); g.stroke(); g.fillText(String(d.getUTCFullYear()), X(i) + 3, H - 4); } }\n  g.strokeStyle = \'#6FB0F0\'; g.lineWidth = 1.6; g.beginPath(); let first = true;\n  for (let i = 0; i < N; i++) { const v = RAWV.flow[i]; if (v == null) { first = true; continue; } const x = X(i), y = Y(v); if (first) { g.moveTo(x, y); first = false; } else g.lineTo(x, y); }\n  g.stroke();\n  g.strokeStyle = \'#FFD24D\'; g.lineWidth = 2; g.beginPath(); g.moveTo(X(S.day), padT); g.lineTo(X(S.day), H - padB); g.stroke();\n}\nfunction renderLeadTable() {\n  const el = document.getElementById(\'hts-leadtable\'); if (!el) return;\n  if (!el.dataset.done) {\n    let h = \'<table class="hts-tbl"><tr><th>Model</th>\' + Array.from({ length: L }, (_, l) => \'<th>+\' + (l + 1) + \'d</th>\').join(\'\') + \'</tr>\';\n    D.models.forEach((n, m) => { h += \'<tr data-m="\' + m + \'"><td>\' + n + \'</td>\' + rmse[m].map((v, l) => \'<td data-l="\' + l + \'">\' + v.toFixed(3) + \'</td>\').join(\'\') + \'</tr>\'; });\n    el.innerHTML = h + \'</table>\'; el.dataset.done = \'1\';\n  }\n  markLead();\n}\nfunction markLead() {\n  const el = document.getElementById(\'hts-leadtable\'); if (!el) return;\n  el.querySelectorAll(\'tr[data-m]\').forEach((tr) => { const on = +tr.getAttribute(\'data-m\') === S.model; tr.classList.toggle(\'hts-cur\', on);\n    tr.querySelectorAll(\'td[data-l]\').forEach((td) => td.classList.toggle(\'hts-curcell\', on && +td.getAttribute(\'data-l\') === S.lead - 1)); });\n}\n// ---------------------------------------------------------------- day application (DOM edition: charts only)\nfunction applyDay() { drawBoard(); drawDayPanel(); drawFcPanel(); drawOverview(); renderLeadTable(); }\nfunction syncCtl() {\n  const ms = document.getElementById(\'hts-model\'); if (ms) ms.value = String(S.model);\n  const ls = document.getElementById(\'hts-lead\'); if (ls) ls.value = String(S.lead);\n  const fs = document.getElementById(\'hts-focus\'); if (fs) fs.value = String(S.focus);\n  const pb = document.getElementById(\'hts-play\'); if (pb) pb.textContent = S.playing ? \'❚❚ Pause\' : \'▶ Play\';\n  const cb = document.getElementById(\'hts-cmp\'); if (cb) cb.textContent = S.compare ? \'Single model\' : \'Compare all\';\n  markLead();\n}\naddEventListener(\'keydown\', (e) => {\n  const t = e.target; if (t && (t.tagName === \'INPUT\' || t.tagName === \'SELECT\' || t.tagName === \'TEXTAREA\' || t.tagName === \'BUTTON\')) return;\n  const k = e.key.toLowerCase();\n  if (k === \' \') { e.preventDefault(); act.play(); }\n  else if (k === \'m\') act.next(); else if (k === \'l\') act.lead(); else if (k === \'c\') act.cmp();\n  else if (k === \'f\') act.col(e.shiftKey ? -1 : 1);\n  else if (k >= \'0\' && k <= \'6\') setFocus(+k - 1);\n  else if (k === \'arrowright\') setDay(S.day + 1); else if (k === \'arrowleft\') setDay(S.day - 1);\n  else if (k === \'u\') goMap(); else return;\n  syncCtl();\n});\nfunction moveEl(id, slotId) { const el = document.getElementById(id), slot = document.getElementById(slotId); if (el && slot) slot.appendChild(el); }\nfunction htStatsInit() {\n  const bs = document.getElementById(\'hts-board-slot\'); if (bs) { B.c.className = \'hts-cv\'; bs.appendChild(B.c); }\n  const ds = document.getElementById(\'hts-day-slot\'); if (ds) { dayPanel.c.className = \'hts-cv\'; ds.appendChild(dayPanel.c); }\n  const fs2 = document.getElementById(\'hts-fc-slot\'); if (fs2) { fcPanel.c.className = \'hts-cv\'; fs2.appendChild(fcPanel.c); }\n  moveEl(\'ht-datewrap\', \'hts-date-slot\');\n  moveEl(\'to3d\', \'hts-nav3d\');\n  moveEl(\'featcpanel\', \'hts-ablation-slot\');\n  moveEl(\'ht-drift-panel\', \'hts-drift-slot\');\n  moveEl(\'ht-dacp-panel\', \'hts-dacp-slot\');\n  const ms = document.getElementById(\'hts-model\');\n  if (ms) { D.models.forEach((n, i) => { const o = document.createElement(\'option\'); o.value = String(i); o.textContent = n; ms.appendChild(o); });\n    ms.addEventListener(\'change\', () => { S.model = +ms.value; S.compare = false; applyDay(); syncCtl(); }); }\n  const ls = document.getElementById(\'hts-lead\');\n  if (ls) { for (let l = 1; l <= L; l++) { const o = document.createElement(\'option\'); o.value = String(l); o.textContent = \'+\' + l + \'d\'; ls.appendChild(o); }\n    ls.addEventListener(\'change\', () => { S.lead = +ls.value; applyDay(); syncCtl(); }); }\n  const fo = document.getElementById(\'hts-focus\');\n  if (fo) { const o0 = document.createElement(\'option\'); o0.value = \'-1\'; o0.textContent = \'Forecast view\'; fo.appendChild(o0);\n    COLS.forEach((C, i) => { const o = document.createElement(\'option\'); o.value = String(i); o.textContent = C.name; fo.appendChild(o); });\n    fo.addEventListener(\'change\', () => { setFocus(+fo.value); syncCtl(); }); }\n  document.querySelectorAll(\'[data-act]\').forEach((b) => b.addEventListener(\'click\', () => { const a = b.getAttribute(\'data-act\');\n    if (a === \'prevday\') setDay(S.day - 1); else if (a === \'nextday\') setDay(S.day + 1);\n    else if (a === \'play\') act.play(); else if (a === \'nextmodel\') act.next(); else if (a === \'nextlead\') act.lead(); else if (a === \'cmp\') act.cmp();\n    syncCtl(); }));\n  const ov = document.getElementById(\'hts-overview\');\n  if (ov) ov.addEventListener(\'click\', (e) => { const r = ov.getBoundingClientRect(); const fx = (e.clientX - r.left) * (ov.width / r.width);\n    const frac = (fx - OV_PADL) / (ov.width - OV_PADL - OV_PADR); setDay(Math.round(Math.max(0, Math.min(1, frac)) * (N - 1))); syncCtl(); });\n  htDateInit();\n  applyDay(); syncCtl();\n  let acc = 0;\n  setInterval(() => { if (!S.playing) return; acc += 0.6; while (acc >= 1) { acc -= 1; setDay(S.day + 1 >= N ? 0 : S.day + 1); } syncCtl(); }, 100);\n}\nif (document.readyState === \'loading\') document.addEventListener(\'DOMContentLoaded\', htStatsInit); else htStatsInit();\n// hook (DOM edition of the original window.HT: no renderer/scene handles)\nwindow.HT = { S, setDay, setFocus, COLS, applyDay, act, predFor, ivFor, actualAt, dayPanel, fcPanel };\nwindow.HT_READY = true;\n'

CSS = '\n/* ht-statsview v1 */\nhtml,body{margin:0;background:#0B1521;color:#E6EDF5;font-family:Arial,system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\n.hts-wrap{max-width:1180px;margin:0 auto;padding:18px 16px 42px}\n.hts-header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n.hts-title h1{margin:0 0 4px;font-size:26px;color:#F5F6F2}\n.hts-sub{color:#8FC1F2;font-size:14px;font-weight:600}\n.hts-sub2{color:#9FB3C8;font-size:12.5px;margin-top:2px}\n.hts-span{display:inline-block;margin-top:8px;padding:3px 10px;border:1px solid #2A3A4A;border-radius:999px;color:#BFD0E0;font-size:12px;background:rgba(12,18,28,.6)}\n.hts-nav{display:flex;gap:8px}\n.hts-navbtn{display:inline-block;padding:9px 14px;border-radius:10px;background:rgba(12,18,28,.85);color:#E6EDF5;font-weight:600;font-size:14px;text-decoration:none;border:1px solid #2A3A4A}\n.hts-navbtn:hover{background:#1B2B45}\n.hts-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin:18px 0 6px}\n.hts-card{background:#101E30;border:1px solid #22344C;border-radius:12px;padding:12px 14px}\n.hts-cl{color:#8FC1F2;font-size:11.5px;font-weight:700;letter-spacing:.04em;text-transform:uppercase}\n.hts-cv{font-size:21px;font-weight:700;margin-top:4px;color:#F5F6F2}\n.hts-cd{color:#9FB3C8;font-size:12px;margin-top:2px}\n.hts-sec{background:#0E1A24;border:1px solid #22344C;border-radius:14px;padding:16px 18px;margin-top:16px}\n.hts-sec h2{margin:0 0 10px;font-size:19px;color:#F5F6F2}\n.hts-sec h3{margin:16px 0 8px;font-size:14.5px;color:#8FC1F2}\n.hts-note{color:#9FB3C8;font-size:12.5px;line-height:1.5}\n.hts-dateslot{margin-bottom:10px}\n#hts-overview{width:100%;height:auto;display:block;border-radius:10px;cursor:pointer}\ncanvas.hts-cv{width:100%;height:auto;display:block}\n.hts-panels{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n@media (max-width:820px){.hts-panels{grid-template-columns:1fr}}\n.hts-ctl{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px}\n.hts-ctl button{background:#23466E;color:#F5F6F2;border:1px solid #2E5A8A;border-radius:8px;padding:7px 12px;font:600 13px Arial;cursor:pointer}\n.hts-ctl button:hover{background:#2E5A8A}\n.hts-ctl label{font-size:13px;color:#9FB3C8;display:flex;align-items:center;gap:6px}\n.hts-ctl select{background:#0E1A24;color:#E8EEF5;border:1px solid #3A4A5E;border-radius:6px;font:600 13px Arial;padding:6px 8px}\n.hts-tbl{border-collapse:collapse;width:100%;font-size:13.5px}\n.hts-tbl th,.hts-tbl td{padding:5px 8px;text-align:right;border-bottom:1px solid #22344C}\n.hts-tbl th{color:#8FC1F2;font-weight:700}\n.hts-tbl td:first-child,.hts-tbl th:first-child{text-align:left}\n.hts-tbl tr.hts-win td{background:rgba(46,158,91,.18);font-weight:700}\n.hts-tbl tr.hts-cur td{background:rgba(143,193,242,.12)}\n.hts-tbl td.hts-curcell{background:rgba(255,210,77,.25);font-weight:700}\n#hts-datewrap{position:static !important;transform:none !important;box-shadow:none !important}\n#featcpanel{position:static !important;max-width:none !important}\n#ht-drift-panel{position:static !important;width:auto !important;max-width:none !important;box-shadow:none !important}\n#ht-drift-panel .htd-body{max-height:none !important;overflow:visible !important}\n#ht-dacp-panel{position:static !important;transform:none !important;max-width:none !important;box-shadow:none !important;justify-content:flex-start !important;margin-top:12px}\n'

LAYOUT = '\n<div class="hts-wrap" id="hts-top">\n <header class="hts-header">\n  <div class="hts-title">\n   <h1>%%NAME%%</h1>\n   <div class="hts-sub">%%META%%</div>\n   <div class="hts-sub2">%%SOURCES%%</div>\n   <div class="hts-span">%%SPAN%%</div>\n  </div>\n  <nav class="hts-nav">%%MAPLINK%%<span id="hts-nav3d"></span></nav>\n </header>\n <section class="hts-cards" aria-label="Record statistics">%%CARDS%%</section>\n <section class="hts-sec" id="hts-sec-hydro">\n  <h2>Hydrograph</h2>\n  <div class="hts-dateslot" id="hts-date-slot"></div>\n  <canvas id="hts-overview" width="1320" height="240"></canvas>\n  <div id="hts-board-slot"></div>\n  <p class="hts-note">Top: the full record (log scale) — the shaded band is the 90-day window drawn below; click the chart to jump to a day. Below: the last 90 days of observed flow with the selected model\'s forecast fan and interval band for the chosen date.</p>\n </section>\n <section class="hts-sec" id="hts-sec-fc">\n  <h2>7-day forecast</h2>\n  <div class="hts-ctl">\n   <button data-act="prevday">◀ Day</button>\n   <button data-act="play" id="hts-play">▶ Play</button>\n   <button data-act="nextday">Day ▶</button>\n   <label>Model <select id="hts-model"></select></label>\n   <button data-act="nextmodel">Next model</button>\n   <label>Lead <select id="hts-lead"></select></label>\n   <button data-act="nextlead">Next lead</button>\n   <button data-act="cmp" id="hts-cmp">Compare all</button>\n   <label>Column <select id="hts-focus"></select></label>\n  </div>\n  <div class="hts-panels"><div id="hts-day-slot"></div><div id="hts-fc-slot"></div></div>\n  <div id="hts-dacp-slot"></div>\n </section>\n <section class="hts-sec" id="hts-sec-models">\n  <h2>Model statistics</h2>\n  <h3>Test-era leaderboard — this station (WY2025–26, log-flow RMSE)</h3>\n  %%STATION_TABLE%%\n  <h3>Pooled leaderboard — all 14 stations (CMP_RMSE, test era)</h3>\n  %%CMP_TABLE%%\n  <h3>RMSE by forecast lead — this station, full record (log-flow)</h3>\n  <div id="hts-leadtable"></div>\n  <p class="hts-note">Per-lead values are computed in your browser from this page\'s baked forecasts — the same matrix the 3D error podium displayed.</p>\n </section>\n <section class="hts-sec" id="hts-sec-ablation">\n  <h2>Feature ablation</h2>\n  <div id="hts-ablation-slot"></div>\n  <p class="hts-note">Precomputed ablation RMSE (test era, 25-year build) per feature subset — the same per-station values as the 3D pages.</p>\n </section>\n <section class="hts-sec" id="hts-sec-drift">\n  <h2>Drift</h2>\n  <div id="hts-drift-slot"></div>\n </section>\n</div>\n'

