def esc(x):
    return html.escape(str(x), quote=True)


def fmt_cfs(v):
    return f"{int(round(v)):,}"


def pctile(sorted_vals, p):
    n = len(sorted_vals)
    if n == 1:
        return sorted_vals[0]
    rank = p / 100.0 * (n - 1)
    lo = int(rank)
    hi = min(lo + 1, n - 1)
    frac = rank - lo
    return sorted_vals[lo] * (1 - frac) + sorted_vals[hi] * frac


def dstr(start, idx):
    return (start + timedelta(days=idx)).strftime("%d %b %Y")


def build_cards(D):
    flow = D["flow"]
    start = date.fromisoformat(D["start"])
    idx = [i for i, v in enumerate(flow) if v is not None]
    vals = sorted(flow[i] for i in idx)
    mean = sum(vals) / len(vals)

    def card(label, value, sub=""):
        return (f'<div class="hts-card"><div class="hts-cl">{label}</div>'
                f'<div class="hts-cv">{value}</div>'
                + (f'<div class="hts-cd">{sub}</div>' if sub else "") + "</div>")

    imax = max(idx, key=lambda i: flow[i])
    imin = min(idx, key=lambda i: flow[i])
    ilast = idx[-1]
    return "".join([
        card("Mean flow", fmt_cfs(mean) + " cfs"),
        card("Median flow", fmt_cfs(pctile(vals, 50)) + " cfs"),
        card("10th percentile", fmt_cfs(pctile(vals, 10)) + " cfs"),
        card("90th percentile", fmt_cfs(pctile(vals, 90)) + " cfs"),
        card("Maximum flow", fmt_cfs(flow[imax]) + " cfs", dstr(start, imax)),
        card("Minimum flow", fmt_cfs(flow[imin]) + " cfs", dstr(start, imin)),
        card("Latest observed", fmt_cfs(flow[ilast]) + " cfs", dstr(start, ilast)),
    ])


def station_table(site):
    rows = sorted(STATION_TEST[site].items(), key=lambda kv: kv[1])
    winner, wv = rows[0]
    trs = ""
    for rank, (name, v) in enumerate(rows, 1):
        cls = ' class="hts-win"' if name == winner else ""
        trs += (f"<tr{cls}><td>{rank}</td><td>{esc(name)}</td><td>{v:.4f}</td>"
                f"<td>#{CMP_POOLED[name][1]} of {len(CMP_POOLED)}</td></tr>")
    return ('<table class="hts-tbl"><tr><th>#</th><th>Model</th><th>Test RMSE (log)</th>'
            "<th>Pooled rank</th></tr>" + trs + "</table>"
            f'<p class="hts-note">Best at this station in the test era: <b>{esc(winner)}</b> '
            f"(RMSE {wv:.4f}, log flow).</p>")


def cmp_table():
    rows = sorted(CMP_POOLED.items(), key=lambda kv: kv[1][1])
    trs = ""
    for name, (v, rank) in rows:
        cls = ' class="hts-win"' if rank == 1 else ""
        trs += f"<tr{cls}><td>{rank}</td><td>{esc(name)}</td><td>{v:.4f}</td></tr>"
    return ('<table class="hts-tbl"><tr><th>Rank</th><th>Model</th><th>Pooled test RMSE (log)</th></tr>'
            + trs + "</table>"
            '<p class="hts-note">Mean of the 14 per-station test-era RMSEs — identical to the '
            "CMP_RMSE leaderboard on the 3D pages. LiveAR is the in-browser learner (not retrained).</p>")


def build_layout(D, site):
    st = D.get("station") or {}
    start = date.fromisoformat(D["start"])
    n = int(D["n"])
    end = start + timedelta(days=n - 1)
    meta = esc(st.get("stationId") or ("USGS-" + site))
    lat, lon = st.get("latitude"), st.get("longitude")
    if lat is not None and lon is not None:
        meta += f" · {lat:.4f}, {lon:.4f}"
    if st.get("drainage"):
        meta += f" · Drainage area {esc(st['drainage'])}"
    span_txt = f"Record: {start.strftime('%d %b %Y')} – {end.strftime('%d %b %Y')} · {n:,} days"
    maplink = (f'<a class="hts-navbtn" href="{esc(st["mapUrl"])}">◀ USA map</a>'
               if st.get("mapUrl") else "")
    out = LAYOUT
    out = out.replace("%%NAME%%", esc(st.get("name") or "HydroTwin station"))
    out = out.replace("%%META%%", meta)
    out = out.replace("%%SOURCES%%", esc(st.get("sources") or ""))
    out = out.replace("%%SPAN%%", span_txt)
    out = out.replace("%%MAPLINK%%", maplink)
    out = out.replace("%%CARDS%%", build_cards(D))
    out = out.replace("%%STATION_TABLE%%", station_table(site))
    out = out.replace("%%CMP_TABLE%%", cmp_table())
    return out


def patch_page(s):
    if MARKER in s:
        return s, "already"
    if "window.HT3D={" in s or "window.HT_DATA={" not in s:
        return None, "not a classic page"
    i = s.find("window.HT_DATA=")
    if i < 0:
        return None, "no HT_DATA"
    j = s.find("</script>", i)
    ht_data_block = s[i:j]
    try:
        D, _ = json.JSONDecoder().raw_decode(s[i + len("window.HT_DATA="):])
    except Exception as e:
        return None, f"HT_DATA parse failed: {e}"
    st = D.get("station") or {}
    site = (st.get("stationId") or "").replace("USGS-", "")
    if site not in STATION_TEST or site not in ABLATION25:
        return None, f"no baked data for site {site!r}"

    # 1. title
    if s.count("<title>HydroTwin VR</title>") != 1:
        return None, "title anchor"
    s = s.replace("<title>HydroTwin VR</title>",
                  f"<title>{esc(st.get('name') or 'HydroTwin station')} · HydroTwin statistics</title>", 1)
    # 2. head stylesheet
    a = s.find("<style>")
    b = s.find("</style>", a) if a >= 0 else -1
    if a < 0 or b < 0:
        return None, "style anchor"
    s = s[:a] + "<style>\n" + CSS + "\n</style>" + s[b + len("</style>"):]
    # 3. importmap (three.js CDN) removal
    a = s.find('<script type="importmap">')
    if a < 0:
        return None, "importmap anchor"
    b = s.find("</script>", a)
    s = s[:a] + s[b + len("</script>"):]
    # 4. module scene script -> DOM statistics app (verbatim data/chart logic)
    blocks = list(re.finditer(r"<script[^>]*>.*?</script>", s, re.S))
    mod = [mm for mm in blocks if 'type="module"' in mm.group(0)[:80]]
    if len(mod) != 1 or "drawBoard" not in mod[0].group(0) or "WebGLRenderer" not in mod[0].group(0):
        return None, "module anchor"
    mm = mod[0]
    s = s[:mm.start()] + "<script>\n" + APP_JS + "\n</script>" + s[mm.end():]
    # 5. VR help overlay -> statistics layout
    a = s.find('<div id="help">')
    if a < 0:
        return None, "help anchor"
    b = s.find("</div>", a)
    s = s[:a] + build_layout(D, site) + s[b + len("</div>"):]
    # 6. restyle the 3D-terrain link (kept as header nav; moved at runtime)
    m2 = re.search(r'<a id="to3d"[^>]*href="([^"]+)"[^>]*>.*?</a>', s, re.S)
    if not m2:
        return None, "to3d anchor"
    s = s[:m2.start()] + f'<a id="to3d" class="hts-navbtn" href="{m2.group(1)}">3D terrain ▶</a>' + s[m2.end():]
    # 7. classic ablation data -> per-station 25-year values (same as 3D pages)
    a = s.find("const ABLATION_C = ")
    if a < 0:
        return None, "ablation anchor"
    j2 = a + len("const ABLATION_C = ")
    try:
        _obj, end = json.JSONDecoder().raw_decode(s[j2:])
    except Exception as e:
        return None, f"ABLATION_C parse failed: {e}"
    s = s[:j2] + json.dumps(ABLATION25[site], ensure_ascii=False) + s[j2 + end:]

    # post-checks: data payload untouched, features intact, scene gone
    if ht_data_block not in s:
        return None, "HT_DATA changed!"
    for token in (MARKER, "ht-dacp v1", "ht-drift-panel", "featcpanel", 'id="ht-date"'):
        if token not in s:
            return None, f"post-check missing {token}"
    for gone in ("importmap", "WebGLRenderer", "Enter VR", "cdn.jsdelivr.net/npm/three"):
        if gone in s:
            return None, f"post-check scene remnant {gone}"
    return s, "patched"


def main():
    pages = sorted(p for p in Path("stations").glob("USGS-*.html") if not p.name.endswith("-3d.html"))
    if not pages:
        print("no classic station pages found (run from repo root)", file=sys.stderr)
        return 1
    n_new = n_skip = n_warn = 0
    for p in pages:
        s = p.read_text(encoding="utf-8")
        out, status = patch_page(s)
        if status == "already":
            n_skip += 1
            print(f"already patched: {p.name}")
            continue
        if out is None:
            n_warn += 1
            print(f"WARNING: {status}, skipped: {p.name}")
            continue
        p.write_text(out, encoding="utf-8")
        n_new += 1
        print(f"patched: {p.name}")
    print(f"patch_statsview: {n_new} page(s) newly patched, {n_skip} already, "
          f"{n_warn} skipped-with-warning, {len(pages)} classic pages scanned")
    return 0


if __name__ == "__main__":
    sys.exit(main())
